-- Source-specific milestone invoice controls.
alter table invoice_csv_artifacts drop constraint invoice_csv_artifacts_schema_version_check;
alter table invoice_csv_artifacts add constraint invoice_csv_artifacts_schema_version_check check(schema_version in ('workos.invoice-tm-csv/1','workos.invoice-milestone-csv/1'));
create function tm_original_invoice_csv_bytes(b invoice_draft_batches) returns bytea language sql stable as $$
 select convert_to('schema_version,batch_id,line_id,line_sequence,item_id,item_version,event_id,snapshot_id,billing_evidence_b64,client_id_b64,contract_id_b64,engagement_id_b64,work_date,eligible_date,currency,amount,period_start,period_end,period_basis'||E'\r\n'||coalesce(string_agg(concat_ws(',', 'workos.invoice-tm-csv/1',b.id::text,l.id::text,l.sequence::text,l.item_id::text,l.item_version::text,l.event_id::text,l.snapshot_id::text,invoice_csv_base64(l.billing_evidence::text),invoice_csv_base64(b.client_id),invoice_csv_base64(b.contract_id),invoice_csv_base64(b.engagement_id),l.billing_evidence->>'workDate',ev.eligible_on::text,l.currency,trim_scale(l.amount)::text,b.period_start::text,b.period_end::text,b.period_basis)||E'\r\n','' order by l.sequence),''),'UTF8')
 from invoice_draft_lines l join billing_eligibility_events ev on ev.id=l.event_id and ev.organization_id=l.organization_id and ev.legal_entity_id=l.legal_entity_id where l.batch_id=b.id
$$;
create or replace function invoice_csv_bytes(b invoice_draft_batches) returns bytea language sql stable as $$
 select case b.source_type when 'TM_SNAPSHOT' then tm_original_invoice_csv_bytes(b) when 'MILESTONE_ACCEPTANCE' then milestone_invoice_csv_bytes(b) else null end
$$;
create or replace function guard_invoice_csv_append() returns trigger language plpgsql as $$
declare ctx jsonb;b invoice_draft_batches;i invoice_batch_approval_instances;p invoice_batch_approval_policies;t invoice_batch_approval_transitions;l invoice_draft_lines;v_count int;v_total numeric;begin
 begin ctx=nullif(current_setting('workos.invoice_csv_context',true),'')::jsonb;exception when others then ctx=null;end;
 select * into b from invoice_draft_batches where id=new.batch_id for update;perform lock_commercial_candidate_identity(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role);
 if b.id is null or ctx is null or new.batch_id::text is distinct from ctx->>'batchId' or new.organization_id is distinct from ctx->>'organizationId' or new.legal_entity_id is distinct from ctx->>'legalEntityId' or new.actor_id::text is distinct from ctx->>'actorId' or new.active_role is distinct from ctx->>'activeRole' or new.operation_id is distinct from ctx->>'operationId' or b.organization_id<>new.organization_id or b.legal_entity_id<>new.legal_entity_id or invoice_batch_governed_state(b.id)<>'Approved' or not invoice_csv_actor_valid(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'create') then raise exception 'An authorized current approved batch is required.' using errcode='ICV01';end if;
 insert into invoice_csv_request_keys(organization_id,legal_entity_id,actor_id,request_id,result_kind,result_id) values(new.organization_id,new.legal_entity_id,new.actor_id,new.request_id,case when tg_table_name='invoice_csv_artifacts' then 'artifact' else 'failure' end,new.id);
 for l in select * from invoice_draft_lines where batch_id=b.id order by sequence loop
  perform invoice_lock_source_witness(b.organization_id,b.legal_entity_id,l,new.actor_id,new.active_role);
  if not invoice_source_line_visible(b.organization_id,b.legal_entity_id,l.batch_id,l.item_id,new.actor_id,new.active_role) then raise exception 'Current worker scope is required for every retained line.' using errcode='ICV01';end if;
  perform 1 from commercial_tm_valuations v join work_submission_evidence e on e.id=v.submission_id join timesheets h on h.id=e.timesheet_id join timesheet_entries te on te.id=v.entry_id and te.timesheet_id=h.id where v.id=l.snapshot_id for share of h,te;
 end loop;
 select * into i from invoice_batch_approval_instances where batch_id=b.id order by sequence desc limit 1;select * into p from invoice_batch_approval_policies where id=i.policy_id;select * into t from invoice_batch_approval_transitions where instance_id=i.id order by sequence desc limit 1;
 if i.id is not null then perform lock_commercial_candidate_identity(i.organization_id,i.legal_entity_id,i.owner_user_id,i.owner_role);perform lock_commercial_candidate_identity(i.organization_id,i.legal_entity_id,i.requester_user_id,i.active_role);for l in select * from invoice_draft_lines where batch_id=b.id order by sequence loop perform invoice_lock_source_witness(b.organization_id,b.legal_entity_id,l,i.owner_user_id,i.owner_role);perform invoice_lock_source_witness(b.organization_id,b.legal_entity_id,l,i.requester_user_id,i.active_role);end loop;end if;
 if i.id is null or p.id is null or t.id is null or t.decision<>'Approved' or t.sequence<>jsonb_array_length(p.definition->'stages') or not invoice_batch_approval_pin_current(i) or i.lineage_hash<>invoice_batch_lineage_hash(b.id) then raise exception 'A current final approval and retained source are required.' using errcode='ICV02';end if;
 if tg_table_name='invoice_csv_failures' then if new.id::text is distinct from ctx->>'failureId' or exists(select 1 from invoice_csv_artifacts a where a.batch_id=b.id) then raise exception 'Only an unaccepted approved operation may record failure.' using errcode='ICV02';end if;return new;end if;
 if new.schema_version is distinct from (case b.source_type when 'TM_SNAPSHOT' then 'workos.invoice-tm-csv/1' when 'MILESTONE_ACCEPTANCE' then 'workos.invoice-milestone-csv/1' else null end) then raise exception 'Source-specific artifact schema required.' using errcode='ICV02';end if;
 select count(*)::int,coalesce(sum(amount),0) into v_count,v_total from invoice_draft_lines where batch_id=b.id;
 if new.id::text is distinct from ctx->>'artifactId' or i.id is null or p.id is null or t.id is null or new.approval_id<>i.id or new.final_transition_id<>t.id or t.decision<>'Approved' or t.sequence<>jsonb_array_length(p.definition->'stages') or not invoice_batch_approval_pin_current(i) or new.lineage_hash<>i.lineage_hash or new.lineage_hash<>invoice_batch_lineage_hash(b.id) or new.line_count<>v_count or new.total<>v_total or new.currency<>b.currency or new.payload is distinct from invoice_csv_bytes(b) or new.sha256<>encode(digest(new.payload,'sha256'),'hex') then raise exception 'Final approval, source lineage, bytes and control totals must match.' using errcode='ICV02';end if;return new;
end $$;

create or replace function complete_invoice_csv_commit() returns trigger language plpgsql as $$
declare b invoice_draft_batches;i invoice_batch_approval_instances;v_action text;v_expected jsonb;begin
 select * into b from invoice_draft_batches where id=new.batch_id;
 if b.id is null or not invoice_csv_actor_valid(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'create') or exists(select 1 from invoice_draft_lines l where l.batch_id=b.id and not invoice_source_line_visible(b.organization_id,b.legal_entity_id,l.batch_id,l.item_id,new.actor_id,new.active_role)) then raise exception 'Current scoped export authority must persist through commit.' using errcode='ICV03';end if;
 if tg_table_name='invoice_csv_artifacts' then
  select * into i from invoice_batch_approval_instances where id=new.approval_id;
  if invoice_batch_governed_state(b.id)<>'Exported' or i.id is null or not invoice_batch_approval_pin_current(i) or new.lineage_hash<>invoice_batch_lineage_hash(b.id) or new.payload is distinct from invoice_csv_bytes(b) or new.sha256<>encode(digest(new.payload,'sha256'),'hex') or new.line_count<>(select count(*) from invoice_draft_lines where batch_id=b.id) or new.total<>(select sum(amount) from invoice_draft_lines where batch_id=b.id) or exists(select 1 from invoice_draft_cancellations where batch_id=b.id) then raise exception 'Artifact, source, occupancy and control totals must commit together.' using errcode='ICV03';end if;
  v_action='Accept CSV';v_expected=jsonb_build_object('batchId',b.id,'artifactId',new.id,'sha256',new.sha256);
 else
  select * into i from invoice_batch_approval_instances where batch_id=b.id order by sequence desc limit 1;
  if invoice_batch_governed_state(b.id)<>'Approved' or i.id is null or not invoice_batch_approval_pin_current(i) or i.lineage_hash<>invoice_batch_lineage_hash(b.id) or exists(select 1 from invoice_csv_artifacts where batch_id=b.id) then raise exception 'Failed generation requires a current approved batch and cannot finalize it.' using errcode='ICV03';end if;
  v_action='Record CSV Failure';v_expected=jsonb_build_object('batchId',b.id,'failureId',new.id,'code',new.code);
 end if;
 if not exists(select 1 from audit_logs a where a.organization_id=b.organization_id and a.legal_entity_id=b.legal_entity_id and a.user_id=new.actor_id::text and a.active_role=new.active_role and a.module='Invoice CSV' and a.action=v_action and a.entity_id=new.id::text and a.operation_id=new.operation_id and a.new_value=v_expected) then raise exception 'Artifact operation and redacted audit must commit together.' using errcode='ICV03';end if;return null;
end $$;

create or replace function guard_invoice_export_notice() returns trigger language plpgsql as $$
declare ctx jsonb;ev invoice_export_notice_events;b invoice_draft_batches;p invoice_export_notice_policies;t jsonb;src record;rel record;expected text[];pref boolean;decision text;rec invoice_export_notice_recipients;latest uuid;recovering boolean;begin
 begin ctx=nullif(current_setting('workos.invoice_notice_event_context',true),'')::jsonb;exception when others then ctx=null;end;
 if ctx is null then raise exception 'An exact protected notification operation is required.' using errcode='INC01';end if;
 if tg_table_name='invoice_export_notice_events' then
  select * into b from invoice_draft_batches where id=new.batch_id;select * into p from invoice_export_notice_policies where id=new.policy_id;
  if new.confirmation_id is not null then select id,batch_id,actor_id,active_role,operation_id into src from invoice_batch_confirmations where id=new.confirmation_id;elsif new.artifact_id is not null then select id,batch_id,actor_id,active_role,operation_id into src from invoice_csv_artifacts where id=new.artifact_id;else select id,batch_id,actor_id,active_role,operation_id into src from invoice_csv_failures where id=new.failure_id;end if;
  select id into latest from invoice_export_notice_policies where organization_id=b.organization_id and legal_entity_id=b.legal_entity_id and engagement_id=b.engagement_id and effective_from<=(clock_timestamp() at time zone 'UTC')::date order by effective_from desc,sequence desc limit 1;
  select exists(select 1 from invoice_export_notice_recoveries z join invoice_export_notice_producer_failures f on f.id=z.producer_failure_id where z.id::text=ctx->>'recoveryId' and z.batch_id=b.id and z.policy_id=p.id and z.actor_id::text=ctx->>'actorId' and z.active_role=ctx->>'activeRole' and (f.artifact_id=new.artifact_id or f.failure_id=new.failure_id or f.confirmation_id=new.confirmation_id) and invoice_csv_actor_valid(z.organization_id,z.legal_entity_id,z.actor_id,z.active_role,'view') and invoice_notice_actor_has(z.organization_id,z.legal_entity_id,z.actor_id,z.active_role,'commercial.invoice_export.recover_notices')) into recovering;
  select x into t from jsonb_array_elements(p.definition->'templates')x where x->>'key'=new.event_key;
  if b.id is null or p.id is null or src.id is null or t is null or new.id::text is distinct from ctx->>'eventId' or b.id::text is distinct from ctx->>'batchId' or p.id::text is distinct from ctx->>'policyId' or src.id::text is distinct from ctx->>'resultId' or (not recovering and (src.actor_id::text is distinct from ctx->>'actorId' or src.active_role is distinct from ctx->>'activeRole')) or src.operation_id is distinct from ctx->>'operationId' or new.operation_id<>src.operation_id or src.batch_id<>b.id or b.organization_id is distinct from ctx->>'organizationId' or b.legal_entity_id is distinct from ctx->>'legalEntityId' or p.organization_id<>b.organization_id or p.legal_entity_id<>b.legal_entity_id or p.engagement_id<>b.engagement_id or (not recovering and p.id is distinct from latest) or new.locale is distinct from p.definition->>'locale' or new.title is distinct from replace(t->>'subject','{{sourceRef}}','invoice-batch/'||b.id::text) or new.body is distinct from replace(t->>'body','{{sourceRef}}','invoice-batch/'||b.id::text) then raise exception 'Exact operation, current policy and sanitized event required.' using errcode='INC02';end if;return new;
 end if;
 if tg_table_name='invoice_export_notice_deliveries' then select * into rec from invoice_export_notice_recipients where id=new.recipient_id;select * into ev from invoice_export_notice_events where id=rec.event_id;else select * into ev from invoice_export_notice_events where id=new.event_id;end if;select * into b from invoice_draft_batches where id=ev.batch_id;select * into p from invoice_export_notice_policies where id=ev.policy_id;
 if ev.id is null or ev.id::text is distinct from ctx->>'eventId' or b.id::text is distinct from ctx->>'batchId' or p.id::text is distinct from ctx->>'policyId' or ev.operation_id is distinct from ctx->>'operationId' then raise exception 'Exact retained event is required.' using errcode='INC02';end if;
 if ctx ? 'recoveryId' and not exists(select 1 from invoice_export_notice_recoveries z left join invoice_export_notice_producer_failures f on f.id=z.producer_failure_id where z.id::text=ctx->>'recoveryId' and z.batch_id=b.id and z.policy_id=p.id and z.actor_id::text=ctx->>'actorId' and z.active_role=ctx->>'activeRole' and (z.event_id=ev.id or(f.artifact_id=ev.artifact_id or f.failure_id=ev.failure_id or f.confirmation_id=ev.confirmation_id)) and invoice_csv_actor_valid(z.organization_id,z.legal_entity_id,z.actor_id,z.active_role,'view') and invoice_notice_actor_has(z.organization_id,z.legal_entity_id,z.actor_id,z.active_role,'commercial.invoice_export.recover_notices')) then raise exception 'Current scoped recovery authority required.' using errcode='INC01';end if;
 if tg_table_name='invoice_export_alert_outbox' then
  if ev.event_key<>'invoice_batch.export_failed' or new.route_id<>p.route_id or new.status<>'Pending' then raise exception 'Exact configured operational route is required.' using errcode='INC02';end if;return new;
 elsif tg_table_name='invoice_export_notice_failures' then return new;
 elsif tg_table_name='invoice_export_notice_deliveries' then
  select * into rec from invoice_export_notice_recipients where id=new.recipient_id;
  if rec.id is null or not rec.in_app then raise exception 'Delivery must match its in-app recipient.' using errcode='INC02';end if;return new;
 end if;
 select array_agg(distinct x.recipient_reason order by x.recipient_reason) into expected from invoice_export_expected_recipients(ev)x where x.recipient=new.user_id;
 for rel in select * from invoice_export_expected_recipients(ev)x where x.recipient=new.user_id loop
  perform lock_commercial_candidate_identity(b.organization_id,b.legal_entity_id,rel.recipient,rel.held_role);
  if not invoice_notice_named_recipient(b.organization_id,b.legal_entity_id,rel.recipient,rel.held_role) or (rel.recipient_reason='finance_billing_owner' and (not invoice_draft_actor_valid(b.organization_id,b.legal_entity_id,rel.recipient,rel.held_role,'view') or exists(select 1 from invoice_draft_lines l where l.batch_id=b.id and not invoice_source_line_visible(b.organization_id,b.legal_entity_id,l.batch_id,l.item_id,rel.recipient,rel.held_role)))) then raise exception 'Current scoped notification recipient required.' using errcode='INC01';end if;
 end loop;
 select n.in_app into pref from notification_preferences n join users u on u.employee_record_id=n.employee_id where u.id=new.user_id and n.event_type=ev.event_key for share of n;
 decision=case when ev.event_key='invoice_batch.export_failed' then 'Required' when not(p.definition->>'completionInApp')::boolean then 'SuppressedPolicy' when pref is false then 'SuppressedPreference' else 'Enabled' end;
 if expected is null or (select array_agg(x order by x) from unnest(new.reasons)x) is distinct from expected or new.channel_decision<>decision or new.in_app is distinct from(decision in('Required','Enabled')) then raise exception 'Exact recipient reasons and channel policy required.' using errcode='INC02';end if;return new;
end $$;
